<script setup>
import {ref} from 'vue';import {store,api,cargar} from '../store';const form=ref({nombre:'',docente:''}),error=ref('');function limpiar(){form.value={nombre:'',docente:''}}async function guardar(){error.value='';try{const c=form.value;await api('/cursos'+(c.id?'/'+c.id:''),c.id?'PUT':'POST',c);limpiar();await cargar()}catch(e){error.value=e.message}}async function eliminar(c){if(!confirm('¿Eliminar curso?'))return;try{await api('/cursos/'+c.id,'DELETE');limpiar();await cargar();error.value=''}catch(e){error.value=e.message}}
</script><template><h2 class="mb-3">Cursos</h2><div v-if="error" class="alert alert-danger">{{error}}</div><form class="card p-3 mb-3" @submit.prevent="guardar"><h5>{{form.id?'Editar curso':'Nuevo curso'}}</h5><div class="row g-2"><label class="col-md-5">Nombre<input class="form-control" v-model.trim="form.nombre" required></label><label class="col-md-5">Docente<input class="form-control" v-model.trim="form.docente"></label><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Guardar</button></div></div><button v-if="form.id" type="button" class="btn btn-link align-self-start" @click="limpiar">Cancelar</button></form><div class="row g-3"><div v-for="c in store.cursos" :key="c.id" class="col-md-6 col-xl-4"><div class="card p-3"><h5>{{c.nombre}}</h5><p class="text-secondary">{{c.docente||'Sin docente'}}</p><p>{{store.tareas.filter(t=>t.curso===c.id).length}} actividades</p><div><button class="btn btn-sm btn-outline-primary me-2" @click="form={...c}">Editar</button><button class="btn btn-sm btn-outline-danger" @click="eliminar(c)">Eliminar</button></div></div></div></div><p v-if="!store.cursos.length">Registra tu primer curso.</p></template>